// Product silver profiles and lens filters through the real C API. These
// checks use the upstream B&W research's tone constraints, not image snapshots
// generated by the implementation. Film-edge acceptance is a separate gate.
#include "spektrafilm/spk_engine.h"
#include "json.hpp"
#include <algorithm>
#include <array>
#include <cmath>
#include <cstdio>
#include <fstream>
#include <iterator>
#include <memory>
#include <stdexcept>
#include <string>
#include <vector>

namespace {
using spk::Json;
void check(bool ok, const std::string& why) { if (!ok) throw std::runtime_error(why); }
Json parse(const std::string& s) { Json j; std::string e; check(Json::parse(s,j,e),e); return j; }
using Session = std::unique_ptr<spk_session, decltype(&spk_session_release)>;
constexpr uint32_t cell = 64;
constexpr std::array<std::array<float,3>,5> patches{{{.184f,.184f,.184f},{.45f,.04f,.03f},
    {.08f,.25f,.06f},{.15f,.28f,.55f},{.03f,.05f,.35f}}};
std::vector<float> chart(bool ramp) {
    const size_t cells = ramp ? 7 : patches.size();
    std::vector<float> pixels(cell*cell*cells*3);
    for(size_t y=0;y<cell;++y) for(size_t x=0;x<cell*cells;++x) for(size_t c=0;c<3;++c)
        pixels[(y*cell*cells+x)*3+c] = ramp ? float(.184*std::exp2(double(x/cell)-3)) : patches[x/cell][c];
    return pixels;
}
Json params(const char* film, const Json& grade) {
    Json j=parse(R"({"print_stock":"ilford_multigrade_iv_rc","grain_active":false,"glare_active":false,"halation_active":false,"dir_couplers_active":false,"auto_exposure":false,"input_cctf_decoding":false,"input_color_space":"sRGB","output_color_space":"sRGB","output_cctf_encoding":true,"c_filter_neutral":0})");
    j.set("film_stock",Json(std::string(film)));
    for(const auto& [k,v]:grade.fields()) j.set(k,v);
    return j;
}
Session open(spk_engine* engine, const std::vector<float>& pixels, const Json& params) {
    spk_image image{pixels.data(),uint32_t(pixels.size()/3/cell),cell,3};
    Session s(spk_open(engine,&image,params.dump().c_str(),nullptr),spk_session_release);
    check(bool(s),std::string("open: ")+spk_last_error(engine)); return s;
}
std::vector<uint16_t> render(spk_engine* engine, spk_session* session, bool* cached=nullptr) {
    // Reprint takes a valid cached negative, so filter invalidation is tested
    // rather than hidden by spk_render's unconditional fresh film request.
    spk_result r{};const auto status=spk_reprint(session,"full",&r);
    if(status!=SPK_OK){spk_result_free(&r);throw std::runtime_error(std::string("render: ")+spk_last_error(engine));}
    check(r.rgba16&&r.width&&r.height,"render returned no pixels");
    std::vector<uint16_t> out(r.rgba16,r.rgba16+size_t(r.width)*r.height*4);
    if(cached)*cached=r.negative_was_cached!=0;
    spk_result_free(&r);return out;
}
std::vector<std::array<double,3>> means(const std::vector<uint16_t>& pixels) {
    const size_t width=pixels.size()/4/cell,cells=width/cell;
    std::vector<std::array<double,3>> out(cells);
    for(size_t k=0;k<cells;++k)for(size_t y=8;y<cell-8;++y)for(size_t x=8;x<cell-8;++x)
        for(size_t c=0;c<3;++c)out[k][c]+=double(pixels[(y*width+k*cell+x)*4+c])/65535/((cell-16)*(cell-16));
    return out;
}
double density(double v) { const double lin=v<=.04045?v/12.92:std::pow((v+.055)/1.055,2.4);return -std::log10(std::max(lin,1e-6)); }
void set(spk_engine* engine,spk_session* s,const Json& delta) {
    const auto status=spk_set_params(s,delta.dump().c_str(),nullptr);
    check(status==SPK_OK,std::string("set_params: ")+spk_last_error(engine));
}
Json state(spk_engine* engine,spk_session* s) {
    char* value=nullptr;const auto status=spk_get_params(s,&value);
    check(status==SPK_OK&&value,std::string("get_params: ")+spk_last_error(engine));
    const std::string text=value;spk_string_free(value);return parse(text);
}
}
int main(int argc,char** argv) {
    try {
        check(argc==2,"usage: spk_vulkan_bw resources_dir");
        std::ifstream file(std::string(argv[1])+"/paper_grades.json");
        check(bool(file),"product paper grades are missing from staged resources");
        const auto grades=parse(std::string(std::istreambuf_iterator<char>(file),{})).at("grades");
        std::unique_ptr<spk_engine,decltype(&spk_engine_destroy)> engine(spk_engine_create(argv[1],nullptr),spk_engine_destroy);
        check(bool(engine),std::string("engine: ")+spk_last_error(nullptr));
        const auto input=chart(false),ramp=chart(true);
        const char* films[]={"kodak_tri_x_400","kodak_tmax_100","fujifilm_neopan_acros_100_ii","ilford_hp5_plus_400"};
        for(const auto* film:films) {
            auto s=open(engine.get(),input,params(film,grades.at("2")));
            const auto original=render(engine.get(),s.get());const auto base=means(original);
            for(const auto& p:base)for(double c:p)check(std::abs(c-p[1])<.002,std::string(film)+": silver print is not neutral");
            const double mid=density(base[0][1]);check(mid>.55&&mid<.95,std::string(film)+": wrong filter-2 midgrey "+std::to_string(mid));
            std::array<std::vector<std::array<double,3>>,2> filtered;
            for(size_t f=0;f<2;++f) {
                set(engine.get(),s.get(),parse(f==0?R"({"camera_filter":"w25"})":R"({"camera_filter":"w47"})"));
                bool cached=true;filtered[f]=means(render(engine.get(),s.get(),&cached));
                check(!cached,"lens filter reused the previous negative");
                check(std::abs(filtered[f][0][1]-base[0][1])<.01,"filter factor moved middle grey");
            }
            const auto& red=filtered[0];const auto& blue=filtered[1];
            check(red[1][1]>base[1][1]+.05&&red[3][1]<base[3][1]-.05&&red[4][1]<base[4][1]-.05,"red filter spectral response is wrong");
            check(blue[4][1]>base[4][1]+.05&&blue[1][1]<base[1][1]-.05,"blue filter spectral response is wrong");
            set(engine.get(),s.get(),parse(R"({"camera_filter":""})"));
            check(render(engine.get(),s.get())==original,"removing the lens filter did not restore exact deterministic pixels");
            const auto before=state(engine.get(),s.get()).dump();
            check(spk_set_params(s.get(),R"({"camera_filter":"w99","print_exposure":1.25})",nullptr)==SPK_ERR_USER,"unknown lens filter was accepted");
            check(state(engine.get(),s.get()).dump()==before,"invalid lens filter partially changed the session");
            std::array<double,3> spans{};size_t n=0;
            for(const char* grade:{"00","2","5"}) {
                auto r=open(engine.get(),ramp,params(film,grades.at(grade)));const auto p=means(render(engine.get(),r.get()));
                spans[n++]=density(p.front()[1])-density(p.back()[1]);
            }
            check(spans[0]<spans[1]&&spans[1]<spans[2]&&spans[2]>1.3*spans[0],"paper grade did not increase print contrast");
            // A colour pair has a measured neutral pack; the silver-paper Y=68
            // must not leak through read_params/carry during a stock switch.
            set(engine.get(),s.get(),parse(R"({"film_stock":"kodak_portra_400","print_stock":"kodak_portra_endura"})"));
            auto colour=params("kodak_portra_400",Json::object());colour.set("print_stock",Json(std::string("kodak_portra_endura")));
            auto fresh=open(engine.get(),input,colour);
            const auto changed=state(engine.get(),s.get()),expected=state(engine.get(),fresh.get());
            for(const char* key:{"c_filter_neutral","m_filter_neutral","y_filter_neutral"})
                check(changed.at(key).as_double()==expected.at(key).as_double(),std::string("silver neutral pack leaked into colour: ")+key);
            std::printf("PASS %s tone, grades, filters, cache and colour return\n",film);
        }
        return 0;
    }catch(const std::exception& e){std::fprintf(stderr,"%s\n",e.what());return 1;}
}
